line-height:1.35;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dnct-reply-preview{display:flex;align-items:center;gap:.5rem;margin:0 0 .45rem}.dnct-reply-preview b,.dnct-reply-quote b{display:block;color:#ddd6fe}.dnct-reply-preview span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dnct-reply-preview button{border:0;background:transparent;color:#c4b5fd;cursor:pointer;font-size:1rem}.dnct-typing-row{display:flex;align-items:center;gap:.4rem;margin:.45rem 0}.dnct-typing-bubble{display:flex;gap:.28rem;padding:.65rem .75rem;border-radius:14px 14px 14px 4px;background:rgba(255,255,255,.07)}.dnct-typing-dot{width:.35rem;height:.35rem;border-radius:50%;background:#c4b5fd;animation:dnct-typing 1.1s ease-in-out infinite}.dnct-typing-dot:nth-child(2){animation-delay:.15s}.dnct-typing-dot:nth-child(3){animation-delay:.3s}@keyframes dnct-typing{0%,60%,100%{transform:translateY(0);opacity:.42}30%{transform:translateY(-.22rem);opacity:1}}.dnct-ticket-bubble{position:relative;width:fit-content;max-width:82%;text-align:left;overflow-wrap:anywhere;word-break:break-word;padding:.65rem .8rem;border-radius:14px 14px 14px 4px;background:rgba(255,255,255,.07);color:#eef2ff;font-size:.78rem;line-height:1.45;white-space:pre-wrap;box-shadow:0 3px 10px rgba(0,0,0,.12)}.dnct-ticket-row.mine .dnct-ticket-author{display:none}.dnct-ticket-row.mine .dnct-ticket-bubble{border-radius:14px 14px 4px 14px;background:linear-gradient(135deg,#7c3aed,#4f46e5);color:#fff}.dnct-ticket-author{display:block;margin-bottom:.2rem;font-size:.63rem;font-weight:800;opacity:.72}.dnct-ticket-state{margin:.35rem auto 0;max-width:17rem;text-align:center;color:#aab2c2;font-size:.72rem;line-height:1.5}.dnct-ticket-composer{display:block;gap:.5rem;align-items:flex-end;margin-top:auto;padding-top:.6rem;border-top:1px solid rgba(255,255,255,.08)}.dnct-ticket-composer textarea{min-height:2.75rem;max-height:7rem;resize:vertical;margin:0}.dnct-ticket-form+.dnct-ticket-conversation{margin-top:0}.dnct-message-state{position:absolute;right:0;bottom:-1.05rem;display:block;color:#9ca3af;font-size:.63rem;line-height:1;white-space:nowrap;opacity:1}.dnct-ticket-reply:focus{outline:none!important;border-color:rgba(255,255,255,.12)!important;box-shadow:none!important}</style>
